const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');
const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';
const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'},api=`https://api.github.com/repos/${repo}/contents/${path}`;const assert=(v,m)=>{if(!v)throw new Error(m)};
async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,ast,decl}}
function identifierCount(ast,name){let count=0;function walk(n){if(!n||typeof n!=='object')return;if(n.type==='Identifier'&&n.name===name)count++;for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return count}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
(async()=>{const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);const p=parse(index.text),nodes=p.decl.filter(n=>n.id.name==='finalRulesFixV510');assert(nodes.length===1,`finalRulesFixV510 declarations ${nodes.length}`);const refs=identifierCount(p.ast,'finalRulesFixV510');assert(refs===1,`finalRulesFixV510 has ${refs-1} external identifier references; refusing cleanup`);const n=nodes[0],code=p.code.slice(0,n.start)+'/* dead finalRulesFixV510 removed: catalog text is authoritative */'+p.code.slice(n.end),html=index.text.slice(0,p.start)+code+index.text.slice(p.sc);const q=parse(html);assert(!q.decl.some(x=>x.id.name==='finalRulesFixV510'),'Dead function remains');assert(q.decl.length===p.decl.length-1,'Unexpected declaration delta');
const oldDom=makeDom(inlineCore(index.text,files),'old'),newDom=makeDom(inlineCore(html,files),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;const oldCore=oldDom.window.SIZA.runArenaCriticalV071(),newCore=newDom.window.SIZA.runArenaCriticalV071();assert(oldCore.passed===oldCore.total&&newCore.passed===newCore.total,'Arena contract failed');assert(oldDom.window.SizaCardCatalog.get('spark').text===newDom.window.SizaCardCatalog.get('spark').text&&oldDom.window.SizaCardCatalog.get('smuggler').text===newDom.window.SizaCardCatalog.get('smuggler').text,'Catalog text changed');console.log(`PASS dead function has zero external refs; Arena ${newCore.passed}/${newCore.total}`);oldDom.window.close();newDom.window.close();const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Remove unused legacy final rules patch',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha)} )().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
